// MIT. Shared values for the municipal GIS handoff application.
import { createHash } from 'node:crypto';
import { canonicalJson } from '../domain.mjs';
export const canonical = canonicalJson;
export const copy = value => JSON.parse(canonical(value));
export function digest(value) { return createHash('sha256').update(typeof value === 'string' || Buffer.isBuffer(value) || value instanceof Uint8Array ? value : canonical(value)).digest('hex'); }
export function fail(code, message, status = 400, details = null) { const error = new Error(message); error.code = code; error.status = status; if (details !== null) error.details = details; throw error; }
export function object(value, name = 'Value') { if (!value || typeof value !== 'object' || Array.isArray(value)) fail('OBJECT_REQUIRED', name + ' must be an object.'); return value; }
export function text(value, name, max = 200, { empty = false } = {}) { if (typeof value !== 'string' || (!empty && !value.trim()) || value.length > max || value.includes('\0')) fail('INVALID_TEXT', name + ' must be ' + (empty ? 'at most ' : '1–') + max + ' characters.'); return value; }
export function instant(value, name) { if (typeof value !== 'string' || !/T.*(?:Z|[+-]\d{2}:\d{2})$/.test(value) || !Number.isFinite(Date.parse(value))) fail('INVALID_DATETIME', name + ' needs an explicit offset or Z.'); return value; }
export function parseJson(value, name = 'JSON file') { if (typeof value !== 'string') fail('ORIGINAL_TEXT_REQUIRED', name + ' must be complete UTF-8 text.'); try { const parsed = JSON.parse(value.charCodeAt(0)===0xFEFF?value.slice(1):value); canonical(parsed); return parsed; } catch (error) { if (error.code === 'INVALID_JSON') throw error; fail('INVALID_JSON', name + ' is not complete finite JSON.'); } }
export const equal = (a, b) => canonical(a) === canonical(b);
export const now = () => new Date().toISOString();
export const entityId = (prefix, identity) => prefix + '-' + digest(identity).slice(0,32);
export function seal(value) { const result = copy(value); delete result.sha256; return { ...result, sha256: digest(result) }; }
export function verifySeal(value, schema) { object(value); const { sha256, ...body } = value; if (schema && value.schema !== schema || !/^[a-f0-9]{64}$/.test(sha256 ?? '') || digest(body) !== sha256) fail('ENTITY_HASH_MISMATCH', 'The complete saved edition does not match its schema and SHA-256.'); return copy(value); }
export function uniqueStrings(value, name, { empty = true, max = 100000 } = {}) { if (!Array.isArray(value) || value.length > max || !empty && !value.length || value.some(v => typeof v !== 'string') || new Set(value).size !== value.length) fail('INVALID_SELECTION', name + ' must be an array of distinct strings.'); return [...value]; }
export function page(rows, filter = {}) { const offset = filter.offset === undefined ? 0 : Number(filter.offset), limit = filter.limit === undefined ? 100 : Number(filter.limit); if (!Number.isSafeInteger(offset) || offset < 0 || !Number.isSafeInteger(limit) || limit < 1 || limit > 1000) fail('INVALID_PAGE', 'Use a nonnegative offset and a limit from 1 to 1000.'); return { items: rows.slice(offset,offset+limit),total:rows.length,offset,limit }; }
export function rowSearch(rows, q = '') { if (typeof q !== 'string') fail('INVALID_SEARCH','Search must be text.'); const terms=q.trim().toLocaleLowerCase().split(/\s+/).filter(Boolean); return !terms.length ? rows : rows.filter(row => { const value = [row.serviceRequestId,row.serviceCode,row.serviceName,row.sourceStatus,row.address,row.description,row.agency,row.sourceStatusNotes,...Object.values(row.operator??{})].map(v=>typeof v==='string'?v:canonical(v??null)).join(' ').toLocaleLowerCase(); return terms.every(term=>value.includes(term)); }); }
export function originalBytes({originalText,contentBase64,format}) { if (format==='gpkg') { if (typeof contentBase64!=='string' || originalText!==undefined) fail('BINARY_FILE_REQUIRED','Use contentBase64 for the complete GeoPackage file.'); const bytes=Buffer.from(contentBase64,'base64'); if(bytes.toString('base64')!==contentBase64)fail('INVALID_BASE64','Use canonical complete base64.'); return bytes; } if(contentBase64!==undefined||typeof originalText!=='string')fail('TEXT_FILE_REQUIRED','Use originalText for the complete UTF-8 analyst file.');return Buffer.from(originalText,'utf8'); }
export const MAX_SOURCE_BYTES = 128 * 1024 * 1024;
export const MAX_PACKAGE_BYTES = 256 * 1024 * 1024;
export const MAX_ROWS = 100000;

// MIT. Standard file columns and explicit analyst-editable fields.
import { canonical, copy, fail, object, text } from './shared.mjs';
export const OPERATOR_COLUMNS = Object.freeze({assigned_team:'assignedTeam',asset_id:'assetId',work_order_id:'workOrderId',priority:'priority',action:'action',due_date:'dueDate',analyst_note:'note'});
export const OPERATOR_FIELDS = Object.freeze(Object.values(OPERATOR_COLUMNS));
export const EMPTY_OPERATOR = Object.freeze({assignedTeam:'',assetId:'',workOrderId:'',priority:'',action:'review',dueDate:'',note:''});
export const SOURCE_COLUMNS = Object.freeze(['feature_key','handoff_id','handoff_sha256','source_key','source_id','source_sha256','service_request_id','capture_id','collection_id','source_observed_at','source_status','source_service_code','source_service_name','source_address','source_description','source_agency','source_requested_at','source_updated_at','source_status_notes','source_closed_at','source_latitude','source_longitude','source_projected_x','source_projected_y','source_geometry_state','source_json','source_review_json','report_context_json']);
export const FILE_COLUMNS = Object.freeze([...SOURCE_COLUMNS,...Object.keys(OPERATOR_COLUMNS)]);
export const columnText = value => value==null?'':typeof value==='object'?canonical(value):String(value);
export function normalizeOperator(input = {}) {
  object(input,'Analyst fields');
  if(Object.keys(input).some(key=>!OPERATOR_FIELDS.includes(key)))fail('UNKNOWN_ANALYST_FIELD','An analyst field is not supported.');
  const value={...EMPTY_OPERATOR,...copy(input)};
  for(const key of OPERATOR_FIELDS)text(value[key],key,key==='note'?20000:500,{empty:true});
  if(!['review','dispatch','defer','dismiss'].includes(value.action))fail('INVALID_ANALYST_ACTION','Choose review, dispatch, defer or dismiss.');
  if(value.dueDate && (!/^\d{4}-\d{2}-\d{2}$/.test(value.dueDate)||!Number.isFinite(Date.parse(value.dueDate+'T00:00:00Z'))||new Date(value.dueDate+'T00:00:00Z').toISOString().slice(0,10)!==value.dueDate))fail('INVALID_DUE_DATE','Use a real YYYY-MM-DD date or an empty due date.');
  return value;
}
export function numericCoordinate(value) {
  if(typeof value==='number')return Number.isFinite(value)?value:null;
  if(typeof value!=='string'||!value.trim()||! /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/.test(value.trim()))return null;
  const result=Number(value);return Number.isFinite(result)?result:null;
}
export function normalizeGeometry(geometry) {
  if(geometry===null)return null;
  object(geometry,'Geometry');
  if(geometry.type!=='Point'||!Array.isArray(geometry.coordinates)||geometry.coordinates.length!==2||geometry.coordinates.some(v=>typeof v!=='number'||!Number.isFinite(v)))fail('INVALID_GEOMETRY','Use a two-dimensional WGS84 Point or NULL geometry.');
  const [longitude,latitude]=geometry.coordinates;
  if(longitude < -180 || longitude > 180 || latitude < -90 || latitude > 90)fail('INVALID_GEOMETRY','Longitude must be −180…180 and latitude −90…90.');
  return {type:'Point',coordinates:[Object.is(longitude,-0)?0:longitude,Object.is(latitude,-0)?0:latitude]};
}
export function sourceGeometry(source) {
  const missing=value=>value===null||value===undefined||typeof value==='string'&&!value.trim();
  const lat=source.lat,long=source.long;
  if(missing(lat)||missing(long))return {geometry:null,geometryStatus:'MISSING_COORDINATES'};
  const latitude=numericCoordinate(lat),longitude=numericCoordinate(long);
  if(latitude===null||longitude===null||latitude < -90||latitude > 90||longitude < -180||longitude > 180)return {geometry:null,geometryStatus:'INVALID_COORDINATES'};
  return {geometry:{type:'Point',coordinates:[longitude,latitude]},geometryStatus:'SOURCE_POINT'};
}
export function flatRow(handoff,row) {
  const s=row.source;
  const out={
    feature_key:row.key,handoff_id:handoff.id,handoff_sha256:handoff.sha256,
    source_key:row.sourceKey,source_id:row.sourceId,source_sha256:row.sourceSha256,service_request_id:row.serviceRequestId,
    capture_id:row.captureId,collection_id:row.collectionId,source_observed_at:row.observedAt,
    source_status:row.sourceStatus,source_service_code:row.serviceCode,source_service_name:row.serviceName,
    source_address:row.address,source_description:row.description,source_agency:row.agency,
    source_requested_at:row.requestedAt,source_updated_at:row.updatedAt,source_status_notes:row.sourceStatusNotes,source_closed_at:row.sourceClosedAt,
    source_latitude:s.lat,source_longitude:s.long,source_projected_x:s.x,source_projected_y:s.y,
    source_geometry_state:row.geometryStatus,source_json:s,source_review_json:row.sourceReview,report_context_json:row.reportContext
  };
  for(const [column,field] of Object.entries(OPERATOR_COLUMNS))out[column]=row.operator[field];
  return Object.fromEntries(FILE_COLUMNS.map(key=>[key,columnText(out[key])]));
}
export function operatorFromFlat(properties) { return normalizeOperator(Object.fromEntries(Object.entries(OPERATOR_COLUMNS).map(([column,field])=>[field,properties[column]]))); }
export const editableRow = row => ({geometry:copy(row.geometry),operator:copy(row.operator)});

// MIT. Original collection and report package intake for GIS operations.
import { validateSource, validateReport, SOURCE_SCHEMA, REPORT_SCHEMA } from '../reporting/domain.mjs';
import { canonical, copy, digest, equal, fail, object, parseJson, text, instant, entityId, MAX_SOURCE_BYTES, MAX_ROWS } from './shared.mjs';
import { sourceGeometry } from './fields.mjs';
export const GIS_SOURCE_SCHEMA = 'commons.open311.gis-source.v1';
const REPORTING_PACKAGE = 'commons.open311.reporting-workspace.v1';
const coverage = source => ({sourceId:source.id,sha256:source.sha256,bytes:source.bytes,workspaceId:source.envelope.workspaceId,revision:source.envelope.revision,collectionId:source.envelope.collection.id,connection:copy(source.envelope.collection.connection),query:copy(source.envelope.collection.query),policy:copy(source.envelope.collection.policy),summary:copy(source.envelope.summary)});
function parseInput(originalText, reportId) {
  if(typeof originalText!=='string'||Buffer.byteLength(originalText)>MAX_SOURCE_BYTES)fail('SOURCE_SIZE','Import a complete source JSON file of at most 128 MiB.',413);
  const input=object(parseJson(originalText,'Source file'),'Source file');
  if(input.schema===SOURCE_SCHEMA){
    if(reportId)fail('INVALID_REPORT_SELECTION','A collection import does not use a report ID.');
    const source=validateSource(originalText);
    return {kind:'collection',name:source.envelope.collection.name,selectedReportId:null,reports:[],sources:[source],selected:source.envelope.requests.map(row=>({source,row,report:null})),coverage:[coverage(source)]};
  }
  if(input.schema!==REPORTING_PACKAGE)fail('UNSUPPORTED_SOURCE','Import a complete Open311 collection JSON or reporting workspace/report JSON package.');
  const {sha256,...body}=input;
  if(sha256!==digest(body)||!Array.isArray(input.records))fail('REPORT_PACKAGE_HASH_MISMATCH','The complete reporting package differs from its saved SHA-256.');
  const sources=new Map(),reports=new Map(),recordIds=new Set();
  for(const record of input.records){
    object(record,'Reporting record');
    const recordKey=record.kind+'/'+record.id;if(recordIds.has(recordKey))fail('DUPLICATE_REPORT_RECORD','The report package repeats a record.');recordIds.add(recordKey);
    if(record.kind==='source'){
      const source=validateSource(record.value?.originalText);
      if(source.id!==record.id||source.sha256!==record.value.sha256||!equal(source.envelope,record.value.envelope))fail('REPORT_SOURCE_MISMATCH','A report source differs from its complete original collection.');
      sources.set(record.id,source);
    }else if(record.kind==='report'){
      const report=validateReport(record.value);
      if(report.id!==record.id)fail('REPORT_ID_MISMATCH','A report record has a different identity.');
      reports.set(report.id,report);
    }
  }
  if(!reports.size)fail('NO_REPORTS','The reporting package contains no saved report.');
  const choices=[...reports.values()].map(report=>({id:report.id,name:report.definition?.name??report.id,rows:report.rows.length}));
  const selectedReportId=reportId??input.selectedReportId??(reports.size===1?[...reports.keys()][0]:null);
  if(!selectedReportId)return {kind:'report',name:'Reporting package',selectedReportId:null,reports:choices,sources:[],selected:[],coverage:[]};
  const report=reports.get(selectedReportId);if(!report)fail('REPORT_NOT_FOUND','The selected report is not in this complete file.',404,{reports:choices});
  if(!Array.isArray(report.sourceIds)||report.sourceIds.some(id=>!sources.has(id)))fail('INCOMPLETE_REPORT_SOURCE','The report package must include every original collection used by the selected report.');
  const selected=report.rows.map(reportRow=>{
    const source=sources.get(reportRow.sourceId);
    const observation=source?.envelope.observations.find(value=>value.key===reportRow.key);
    const version=observation?.versions.find(value=>value.sourceSha256===reportRow.sourceSha256);
    if(!source||!version||!equal(version.item.source,reportRow.source)||!version.occurrences.some(value=>value.captureId===reportRow.captureId))fail('REPORT_ROW_SOURCE_MISMATCH','A report row is not bound to an original captured request version.');
    const originalReview=source.envelope.requests.find(value=>value.key===reportRow.key)?.review??null;
    return {source,row:{...copy(version.item),captureId:reportRow.captureId,review:copy(originalReview)},report:reportRow,reportEdition:report};
  });
  return {kind:'report',name:report.definition?.name??report.id,selectedReportId,reports:choices,sources:report.sourceIds.map(id=>sources.get(id)),selected,coverage:report.sourceIds.map(id=>coverage(sources.get(id)))};
}
function normalizedRow(item, inputSourceId) {
  const {source,row,report,reportEdition}=item,c=source.envelope.collection;
  const capture=source.envelope.originals.find(value=>value.capture.id===row.captureId)?.capture;
  if(!capture)fail('SOURCE_CAPTURE_MISSING','The selected source row has no retained capture.');
  const sourceIdentity={baseUrl:c.connection.baseUrl,jurisdictionId:c.connection.jurisdictionId??'',serviceRequestId:row.serviceRequestId};
  const point=sourceGeometry(row.source),context=report?{
    reportId:reportEdition.id,reportSha256:reportEdition.sha256,profileId:reportEdition.profileId,
    definition:copy(reportEdition.definition),group:report.group??null,priority:report.priority??null,
    target:copy(report.target??null),issues:copy(report.issues??[]),
    commentary:reportEdition.commentary??'',requestComment:copy(reportEdition.requestComments?.[row.key]??null),
    reviewStatus:report.reviewStatus??null,assignee:report.assignee??null,reviewDueDate:report.reviewDueDate??null
  }:null;
  return {key:entityId('feature',sourceIdentity),sourceIdentity,sourceKey:row.key,sourceId:inputSourceId,
    originalSourceId:source.id,serviceRequestId:row.serviceRequestId,sourceSha256:row.sourceSha256,captureId:capture.id,
    collectionId:c.id,observedAt:capture.capturedAt,serviceCode:row.serviceCode??null,serviceName:row.serviceName??null,
    sourceStatus:row.status??null,sourceStatusNotes:typeof row.source.status_notes==='string'?row.source.status_notes:row.source.status_notes==null?'':canonical(row.source.status_notes),
    sourceClosedAt:report?.sourceClosedAt??null,description:row.description??null,address:row.address??null,
    agency:copy(row.agency??null),requestedAt:row.requestedAt??null,updatedAt:row.updatedAt??null,
    source:copy(row.source),sourceReview:copy(row.review??null),reportContext:context,
    geometryStatus:point.geometryStatus,originalGeometry:copy(point.geometry),geometry:copy(point.geometry)};
}
function counts(rows){return {rows:rows.length,located:rows.filter(r=>r.geometry!==null).length,unlocated:rows.filter(r=>r.geometry===null).length,invalidGeometry:rows.filter(r=>r.geometryStatus==='INVALID_COORDINATES').length};}
export function inspectSource(originalText,{reportId}={}){
  const parsed=parseInput(originalText,reportId),sha256=digest(originalText),id=entityId('gis-source',{sha256,reportId:parsed.selectedReportId});
  const rows=parsed.selected.map(item=>normalizedRow(item,id));
  if(rows.length>MAX_ROWS)fail('SOURCE_ROW_LIMIT','Use source selections with at most 100,000 selected requests.',413);
  return {kind:parsed.kind,name:parsed.name,sha256,bytes:Buffer.byteLength(originalText),reports:parsed.reports,selectedReportId:parsed.selectedReportId,summary:parsed.kind==='report'&&!parsed.selectedReportId?null:counts(rows)};
}
export function importSource(originalText,{reportId,name,importedAt}={}){
  const parsed=parseInput(originalText,reportId);
  if(parsed.kind==='report'&&!parsed.selectedReportId)fail('REPORT_SELECTION_REQUIRED','Choose one of the saved reports in this package.',400,{reports:parsed.reports});
  const sha256=digest(originalText),id=entityId('gis-source',{sha256,reportId:parsed.selectedReportId});
  const rows=parsed.selected.map(item=>normalizedRow(item,id));if(rows.length>MAX_ROWS)fail('SOURCE_ROW_LIMIT','Use source selections with at most 100,000 selected requests.',413);
  const connections=[...new Map(parsed.sources.map(source=>{const c=source.envelope.collection.connection;return [canonical([c.baseUrl,c.jurisdictionId??'']),{baseUrl:c.baseUrl,jurisdictionId:c.jurisdictionId??'',name:c.name??c.id,attribution:copy(c.attribution??{})}];})).values()];
  return {schema:GIS_SOURCE_SCHEMA,id,kind:parsed.kind,name:text(name??parsed.name,'Source name',200),sha256,bytes:Buffer.byteLength(originalText),
    reportId:parsed.selectedReportId,importedAt:instant(importedAt,'Import time'),originalText,rows,counts:counts(rows),connections,coverage:parsed.coverage};
}
export function sourceSummary(source){const {schema,originalText,rows,...summary}=source;return copy(summary);}
export function sourceVersions(source,key){
  const parsed=parseInput(source.originalText,source.reportId);
  const values=[];
  for(const original of parsed.sources){
    const c=original.envelope.collection;
    for(const observation of original.envelope.observations){
      const featureKey=entityId('feature',{baseUrl:c.connection.baseUrl,jurisdictionId:c.connection.jurisdictionId??'',serviceRequestId:observation.serviceRequestId});
      if(featureKey!==key)continue;
      for(const version of observation.versions)values.push({sourceId:source.id,originalSourceId:original.id,sourceSha256:version.sourceSha256,item:copy(version.item),occurrences:copy(version.occurrences)});
    }
  }
  return values;
}

// MIT. Immutable GIS handoffs, analyst proposals and reviewed dispatch editions.
import { copy, digest, equal, fail, object, text, instant, uniqueStrings, entityId, seal, verifySeal, rowSearch, MAX_ROWS } from './shared.mjs';
import { EMPTY_OPERATOR, OPERATOR_FIELDS, SOURCE_COLUMNS, FILE_COLUMNS, columnText, normalizeOperator, normalizeGeometry, flatRow, operatorFromFlat, editableRow } from './fields.mjs';
export const HANDOFF_SCHEMA='commons.open311.gis-handoff.v1';
export const RETURN_SCHEMA='commons.open311.gis-return.v1';
export const DECISION_SCHEMA='commons.open311.gis-decision.v1';
export const DISPATCH_SCHEMA='commons.open311.gis-dispatch.v1';
export const ANALYST_SCHEMA='commons.open311.gis-analyst.v1';
function values(value,name){if(value===undefined)return [];if(!Array.isArray(value)||value.some(v=>v!==null&&typeof v!=='string')||new Set(value).size!==value.length)fail('INVALID_FILTER',name+' must contain distinct source values.');return copy(value);}
export function normalizeDefinition(value){
  object(value,'Handoff definition');
  const filter=object(value.filters??{},'Source filters');
  if(Object.keys(filter).some(k=>!['q','statuses','serviceCodes','geometry'].includes(k)))fail('UNKNOWN_FILTER','The source filter contains an unknown field.');
  const geometry=filter.geometry??'any';if(!['any','located','unlocated'].includes(geometry))fail('INVALID_GEOMETRY_FILTER','Choose any, located or unlocated.');
  return {name:text(value.name,'Handoff name',200),sourceIds:uniqueStrings(value.sourceIds,'Source editions',{empty:false,max:1000}),
    predecessorId:value.predecessorId==null?null:text(value.predecessorId,'Predecessor handoff',120),
    filters:{q:text(filter.q??'','Search',2000,{empty:true}),statuses:values(filter.statuses,'Source statuses'),serviceCodes:values(filter.serviceCodes,'Service codes'),geometry},
    defaults:normalizeOperator(value.defaults??{})};
}
function rowCounts(rows){return {rows:rows.length,located:rows.filter(r=>r.geometry!==null).length,unlocated:rows.filter(r=>r.geometry===null).length,
  invalidGeometry:rows.filter(r=>r.geometry===null&&r.geometryStatus==='INVALID_COORDINATES').length,
  dispatchReady:rows.filter(r=>r.operator.action==='dispatch'&&r.lastDecisionId).length,changedSources:rows.filter(r=>r.sourceChanged).length};}
export function handoffSummary(handoff,head=false){return {id:handoff.id,seriesId:handoff.seriesId,edition:handoff.edition,predecessorId:handoff.predecessorId,name:handoff.name,sha256:handoff.sha256,createdAt:handoff.createdAt,sourceIds:copy(handoff.sourceIds),counts:copy(handoff.counts),head};}
function sourceOrder(a,b){return Date.parse(a.observedAt)-Date.parse(b.observedAt)||a.sourceSha256.localeCompare(b.sourceSha256)||a.captureId.localeCompare(b.captureId)||a.sourceId.localeCompare(b.sourceId);}
export function createHandoff(input,sources,identity,{predecessor=null}={}){
  const definition=normalizeDefinition(input),byId=new Map(sources.map(source=>[source.id,source]));
  if(definition.sourceIds.some(id=>!byId.has(id)))fail('SOURCE_NOT_FOUND','A selected complete source edition is missing.',404);
  if(definition.predecessorId!==(predecessor?.id??null))fail('PREDECESSOR_MISMATCH','The selected previous handoff does not match.');
  const selected=definition.sourceIds.flatMap(id=>byId.get(id).rows).sort(sourceOrder),winner=new Map();
  for(const row of selected)winner.set(row.key,row);
  if(winner.size>MAX_ROWS)fail('HANDOFF_ROW_LIMIT','A handoff supports up to 100,000 selected request identities.',413);
  const previous=new Map((predecessor?.rows??[]).map(row=>[row.key,row]));
  let rows=[...winner.values()].map(sourceRow=>{
    const before=previous.get(sourceRow.key),same=before?.sourceSha256===sourceRow.sourceSha256;
    return {...copy(sourceRow),geometry:same?copy(before.geometry):copy(sourceRow.geometry),
      operator:same?copy(before.operator):copy(definition.defaults),lastDecisionId:same?before.lastDecisionId:null,
      geometryOrigin:same?(before.geometryOrigin??'source'):'source',sourceChanged:!!before&&!same,
      previousSourceSha256:before?.sourceSha256??null};
  });
  const f=definition.filters;
  rows=rowSearch(rows,f.q).filter(row=>(!f.statuses.length||f.statuses.includes(row.sourceStatus))&&(!f.serviceCodes.length||f.serviceCodes.includes(row.serviceCode))&&(f.geometry==='any'||f.geometry==='located'&&row.geometry!==null||f.geometry==='unlocated'&&row.geometry===null)).sort((a,b)=>a.key.localeCompare(b.key));
  const id=text(identity.id,'Handoff identity',120);
  const coverage=definition.sourceIds.flatMap(sourceId=>byId.get(sourceId).coverage.map(item=>({inputSourceId:sourceId,...copy(item)})));
  return seal({schema:HANDOFF_SCHEMA,id,seriesId:predecessor?.seriesId??id,edition:(predecessor?.edition??0)+1,predecessorId:predecessor?.id??null,
    name:definition.name,createdAt:instant(identity.createdAt,'Handoff time'),sourceIds:copy(definition.sourceIds),definition,rows,coverage,
    counts:rowCounts(rows),decisionHistory:copy(predecessor?.decisionHistory??[]),
    interpretation:'Latest observed original request version across the selected source editions. GIS edits are separate from the source record.'});
}
function changeFields(before,after){const fields=[];if(!equal(before.geometry,after.geometry))fields.push('geometry');for(const key of OPERATOR_FIELDS)if(before.operator[key]!==after.operator[key])fields.push('operator.'+key);return fields;}
export function analystReturn(handoff,decoded,input,identity){
  verifySeal(handoff,HANDOFF_SCHEMA);
  const analyst=text(input.analyst,'Analyst',200),name=text(input.name??('Analyst return — '+analyst),'Return name',200);
  if(!['gpkg','geojson','csv','json'].includes(input.format))fail('INVALID_RETURN_FORMAT','Choose gpkg, geojson, csv or json.');
  const original=copy(object(input.original,'Complete analyst file'));
  if(original.encoding!=='base64'||typeof original.body!=='string')fail('ORIGINAL_RETURN_REQUIRED','Keep the complete original analyst file.');
  const bytes=Buffer.from(original.body,'base64');if(bytes.toString('base64')!==original.body||bytes.length!==original.bytes||digest(bytes)!==original.sha256)fail('ORIGINAL_RETURN_MISMATCH','The analyst file differs from its saved bytes and SHA-256.');
  const rows=new Map(handoff.rows.map(row=>[row.key,row])),changes=[],conflicts=[],seen=new Set(),duplicates=new Set();
