      await atomicJson(directory, 'quota.json', { ...state, revision: state.revision + 1, cooldownUntil: Math.max(state.cooldownUntil, until) });
    });
  }
  return { directory, snapshot, reserve, observe, async close() { closed = true; await pending; } };
}

